// The parse tree of a finished parse, from the nonterminal node that spans the input.
pub fn create_parse_tree<'a>(
    root_id: ids::SPPFNodeId,
    parser: &parser::GroupParser,
    builder: &GroupParseTreeBuilder<'a>,
) -> ParseTree<'a> {
    let iguana_runtime::sppf::SPPFNode::Nonterminal(root) =
        iguana_runtime::parser::Parser::sppf_node(parser, root_id)
    else {
        panic!("the SPPF root is not a nonterminal node")
    };
    match root.nonterminal_id {
        grammar::A => ParseTree::A(visit_sppf(root_id, parser, builder).unwrap_a()),
        grammar::B => ParseTree::B(visit_sppf(root_id, parser, builder).unwrap_b()),
        grammar::C => ParseTree::C(visit_sppf(root_id, parser, builder).unwrap_c()),
        grammar::D => ParseTree::D(visit_sppf(root_id, parser, builder).unwrap_d()),
        grammar::GROUP_0 => {
            ParseTree::Group0(visit_sppf(root_id, parser, builder).unwrap_group_0())
        }
        grammar::START_A | grammar::START_B | grammar::START_C | grammar::START_D => {
            ParseTree::Start(visit_sppf(root_id, parser, builder).unwrap_start())
        }
        _ => panic!(),
    }
}
